var p = msg.payload;
var ts = p.timestamp || Math.floor(Date.now()/1000);

// Build display data
var time = new Date(ts * 1000).toLocaleTimeString('en-GB');
var date = new Date(ts * 1000).toLocaleDateString('en-GB');
p.displayTime = time + ' ' + date;
p.lateFlag = p.isLate ? '⚠ LATE' : '';

// Store full payload for feed update
flow.set('lastTap', p);

// Sanitize strings to prevent SQL issues
var uid    = (p.uid    || '').replace(/'/g, "''");
var name   = (p.name   || '').replace(/'/g, "''");
var action = (p.action || '').replace(/'/g, "''");
var access = (p.access || '').replace(/'/g, "''");

// Message 1 → Save Tap (SQLite fixed query)
var dbMsg = {
    topic: "INSERT INTO attendance (uid, name, action, access, timestamp, isLate, checkInTime, demo) VALUES ('" + uid + "','" + name + "','" + action + "','" + access + "'," + ts + "," + (p.isLate ? 1 : 0) + "," + (p.checkInTime || 0) + "," + (p.demo ? 1 : 0) + ")",
    payload: p
};

// Message 2 → Update Live Feed
var feedMsg = { payload: p };

return [dbMsg, feedMsg];

var p = msg.payload;
var feed = flow.get('tapFeed') || [];
var ts = p.timestamp || Math.floor(Date.now()/1000);
var time = new Date(ts * 1000).toLocaleTimeString('en-GB');
var date = new Date(ts * 1000).toLocaleDateString('en-GB');

var row = {
  time: time + ' ' + date,
  name: p.name || p.uid,
  action: p.action,
  access: p.access,
  late: p.isLate ? '⚠' : '',
  demo: p.demo ? '[DEMO]' : ''
};

feed.unshift(row);
if (feed.length > 50) feed = feed.slice(0, 50);
flow.set('tapFeed', feed);

msg.payload = feed;
return msg;

var p = msg.payload;
var ts = p.timestamp || Math.floor(Date.now()/1000);
var time = new Date(ts * 1000).toLocaleTimeString('en-GB');

var alerts = flow.get('alerts') || [];
alerts.unshift({
  time: time,
  type: p.type,
  uid: p.uid || 'N/A',
  demo: p.demo ? '[DEMO]' : ''
});
if (alerts.length > 20) alerts = alerts.slice(0, 20);
flow.set('alerts', alerts);

msg.payload = { alertList: alerts };
return msg;

var p = msg.payload;
flow.set('doorStatus', p.event);
msg.payload = p;
return msg;

flow.set('espStatus', msg.payload);
msg.payload = msg.payload;
return msg;

flow.set('lastScannedUID', msg.payload.uid);
msg.payload = msg.payload;
return msg;

var rows = msg.payload;
var csv = 'ID,UID,Name,Action,Access,Timestamp,Time,IsLate,Demo\n';
rows.forEach(function(r) {
  var t = new Date(r.timestamp * 1000).toLocaleString('en-GB');
  csv += [r.id, r.uid, r.name, r.action, r.access, r.timestamp, t, r.isLate ? 'YES' : 'NO', r.demo ? 'YES' : 'NO'].join(',') + '\n';
});
msg.payload = csv;
msg.headers = {
  'Content-Type': 'text/csv',
  'Content-Disposition': 'attachment; filename="attendance.csv"'
};
return msg;

flow.set('tapFeed', []);
flow.set('alerts', []);

// Message 1 → HTTP response
var httpMsg = { payload: {success: true}, res: msg.res, req: msg.req };

// Message 2 → MQTT presence reset
var mqttMsg = { payload: JSON.stringify({action: "RESET_ALL"}) };

return [httpMsg, mqttMsg];

var b = msg.payload;
var topic = b.topic;
var payload = b.payload;

if (!topic || !payload) {
    msg.payload = {error: 'missing topic or payload'};
    msg.statusCode = 400;
    return [null, msg];
}

msg.topic = topic;
msg.payload = typeof payload === 'string' ? payload : JSON.stringify(payload);

// Clone message for HTTP response
var resmsg = {
    payload: {success: true},
    statusCode: 200,
    _msgid: msg._msgid,
    res: msg.res,
    req: msg.req
};

node.send([[msg], [resmsg]]);
return null;

